-- fir_decim: one sequential MAC, 111-sample delay line, decimation by 5 (T3.19, 1/2).
--
-- The arithmetic is the contract in Architecture §5.6 (ADR-14):
--   y[m] = sat16((sum_{k=0}^{110} q[k] * x[5m - k] + 2^14) >> 15)
--   x[n < 0] = 0, >> is an arithmetic shift (nearest, halves toward +inf).
-- q comes from fir_coeffs_pkg, generated by hw/gen/gen_fir_coeffs.py. The
-- accumulator is 40 bits, so it matches Python and cannot overflow.
--
-- Interface (one clock aclk, synchronous active-low reset aresetn):
--   clear      1 cycle: empty the delay line and the phase counter. Taken in
--              any state; an input on the same cycle is ignored.
--   in_valid   an int16 sample is offered, taken when in_valid and in_ready.
--   in_data    the sample, two's complement.
--   in_ready   1 only while idle (not during the MAC, the rounding cycle, or
--              the output cycle) and clear is low.
--   out_valid  1 for exactly one cycle when out_data is a new sample.
--   out_data   the int16 output. Samples at input indices 0, 5, 10, ... produce
--              an output. The MAC is one tap per cycle (111 cycles), then one
--              cycle to round and saturate, then one cycle with out_valid.
--   coef_id    fir_coef_id on 32 bits, from the generated package.
--
-- clear or aresetn drops a MAC in progress. The delay line is not wiped: taps
-- older than the samples since the last clear are read as 0.
--
-- Conventions: VHDL-2008, ieee.numeric_std only, one clock, no vendor primitive.

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.fir_coeffs_pkg.all;

entity fir_decim is
  port (
    aclk      : in  std_logic;
    aresetn   : in  std_logic;
    clear     : in  std_logic;
    in_valid  : in  std_logic;
    in_data   : in  std_logic_vector(15 downto 0);
    in_ready  : out std_logic;
    out_valid : out std_logic;
    out_data  : out std_logic_vector(15 downto 0);
    coef_id   : out std_logic_vector(31 downto 0)
  );
end entity fir_decim;

architecture rtl of fir_decim is
  type state_t is (ST_IDLE, ST_MAC, ST_ROUND, ST_EMIT);
  type sample_mem is array (0 to TAP_COUNT - 1) of signed(15 downto 0);

  constant ROUND_BIAS : signed(39 downto 0) := to_signed(2 ** 14, 40);

  signal state      : state_t := ST_IDLE;
  signal phase      : unsigned(2 downto 0) := (others => '0');
  signal filled     : unsigned(6 downto 0) := (others => '0');
  signal wr         : unsigned(6 downto 0) := (others => '0');
  signal tap        : unsigned(6 downto 0) := (others => '0');
  signal acc        : signed(39 downto 0) := (others => '0');
  signal delay_line : sample_mem := (others => (others => '0'));
  signal tap_addr   : natural range 0 to TAP_COUNT - 1 := 0;
  signal tap_sample : signed(15 downto 0) := (others => '0');

  function older(next_wr : unsigned(6 downto 0); index : unsigned(6 downto 0))
    return natural is
    variable slot : integer;
  begin
    -- next_wr is the slot after the newest sample. Tap 0 is that newest sample.
    slot := to_integer(next_wr) - 1 - to_integer(index);
    if slot < 0 then
      slot := slot + TAP_COUNT;
    end if;
    return slot;
  end function;

  function sat16(value : signed(39 downto 0)) return signed is
    variable result : signed(15 downto 0);
  begin
    if value > to_signed(32767, 40) then
      result := to_signed(32767, 16);
    elsif value < to_signed(-32768, 40) then
      result := to_signed(-32768, 16);
    else
      result := resize(value, 16);
    end if;
    return result;
  end function;

begin
  -- The port and the package constant share one name (VHDL is case-insensitive).
  coef_id <= work.fir_coeffs_pkg.COEF_ID;
  in_ready <= '1' when state = ST_IDLE and aresetn = '1' and clear = '0' else '0';

  tap_addr <= older(wr, tap);
  tap_sample <= delay_line(tap_addr) when tap < filled else (others => '0');

  control : process (aclk)
    variable term     : signed(31 downto 0);
    variable rounded  : signed(39 downto 0);
    variable saturated : signed(15 downto 0);
  begin
    if rising_edge(aclk) then
      if aresetn = '0' or clear = '1' then
        state <= ST_IDLE;
        phase <= (others => '0');
        filled <= (others => '0');
        wr <= (others => '0');
        tap <= (others => '0');
        acc <= (others => '0');
        out_valid <= '0';
        out_data <= (others => '0');
      elsif state = ST_IDLE then
        out_valid <= '0';
        if in_valid = '1' then
          delay_line(to_integer(wr)) <= signed(in_data);
          if wr = TAP_COUNT - 1 then
            wr <= (others => '0');
          else
            wr <= wr + 1;
          end if;
          if filled < TAP_COUNT then
            filled <= filled + 1;
          end if;
          if phase = 0 then
            state <= ST_MAC;
            tap <= (others => '0');
            acc <= (others => '0');
            phase <= to_unsigned(1, phase'length);
          elsif phase = DECIMATION - 1 then
            phase <= (others => '0');
          else
            phase <= phase + 1;
          end if;
        end if;
      elsif state = ST_MAC then
        term := to_signed(COEFS(to_integer(tap)), 16) * tap_sample;
        acc <= acc + resize(term, 40);
        if tap = TAP_COUNT - 1 then
          state <= ST_ROUND;
        else
          tap <= tap + 1;
        end if;
      elsif state = ST_ROUND then
        rounded := shift_right(acc + ROUND_BIAS, 15);
        saturated := sat16(rounded);
        out_data <= std_logic_vector(saturated);
        out_valid <= '1';
        state <= ST_EMIT;
      else
        out_valid <= '0';
        state <= ST_IDLE;
      end if;
    end if;
  end process;
end architecture rtl;
